css:
.bg {
  width: 444px;
  height: 444px;
  display: flex;
  justify-content: center;
  align-items: center;
  background: radial-gradient(circle at 50% 40%, #e2e8f0, #94a3b8);
  transition: background 1.5s cubic-bezier(0.4, 0, 0.2, 1);
  font-family: sans-serif;
  border-radius: 30px;
  user-select: none;
}

.bg:has(.theme-switch input:checked) {
  background: radial-gradient(circle at 50% 40%, #fdf2f8, #fbcfe8);
}

.theme-switch {
  position: relative;
  display: inline-flex;
  width: 28vmin;
  height: 17vmin;
  -webkit-tap-highlight-color: transparent;
}

.theme-switch input {
  display: none;
}

.easel-frame {
  position: relative;
  width: 100%;
  height: 100%;
  background: linear-gradient(135deg, #f8fafc, #e2e8f0);
  border: 0.6vmin solid #78350f;
  border-radius: 1vmin;
  box-shadow:
    0 2vmin 4vmin rgba(0, 0, 0, 0.3),
    inset 0 0 0 1.2vmin #fdfbf7,
    inset 0 0.2vmin 1vmin 1.2vmin rgba(0, 0, 0, 0.1),
    inset 0 0 0 1.4vmin #d6d3d1;
  overflow: hidden;
  cursor: pointer;
  transition:
    transform 0.2s cubic-bezier(0.4, 0, 0.2, 1),
    box-shadow 1.5s ease;
}

.easel-frame::before {
  content: "";
  position: absolute;
  inset: -0.6vmin;
  border: 0.2vmin solid #451a03;
  border-radius: 0.6vmin;
  pointer-events: none;
  z-index: 20;
}

.theme-switch input:checked ~ .easel-frame {
  box-shadow:
    0 2.5vmin 5vmin rgba(244, 114, 182, 0.25),
    0 0 4vmin rgba(251, 113, 133, 0.15),
    inset 0 0 0 1.2vmin #fdfbf7,
    inset 0 0.2vmin 1vmin 1.2vmin rgba(0, 0, 0, 0.05),
    inset 0 0 0 1.4vmin #d6d3d1;
}

.canvas-texture {
  position: absolute;
  inset: 1.4vmin;
  background-image: radial-gradient(
      rgba(0, 0, 0, 0.04) 0.1vmin,
      transparent 0.1vmin
    ),
    radial-gradient(rgba(0, 0, 0, 0.02) 0.1vmin, transparent 0.1vmin);
  background-size:
    0.6vmin 0.6vmin,
    0.4vmin 0.4vmin;
  background-position:
    0 0,
    0.2vmin 0.2vmin;
  z-index: 1;
  pointer-events: none;
}

.sketch-scene {
  position: absolute;
  inset: 1.4vmin;
  background: #fdfbf7;
  z-index: 1;
}

.s-sun {
  position: absolute;
  bottom: 5.5vmin;
  left: 12.5vmin;
  width: 4vmin;
  height: 4vmin;
  border-radius: 50%;
  border: 0.15vmin dashed #94a3b8;
  box-shadow: inset 0 0 0.5vmin rgba(148, 163, 184, 0.2);
}

.s-mountain {
  position: absolute;
  border-top: 0.15vmin solid #94a3b8;
  border-radius: 40% 60% 50% 50% / 50% 50% 60% 40%;
  background: transparent;
}

.s-mountain::after {
  content: "";
  position: absolute;
  inset: 0.2vmin;
  border-top: 0.1vmin dashed #cbd5e1;
  border-radius: 40% 60% 50% 50% / 50% 50% 60% 40%;
}

.sm1 {
  bottom: -2vmin;
  left: 1vmin;
  width: 8vmin;
  height: 6vmin;
  transform: rotate(-10deg);
}
.sm2 {
  bottom: -3vmin;
  left: 6vmin;
  width: 10vmin;
  height: 8vmin;
  transform: rotate(5deg);
}
.sm3 {
  bottom: -1vmin;
  left: 14vmin;
  width: 7vmin;
  height: 5vmin;
  transform: rotate(-5deg);
}

.s-water {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 3.5vmin;
  border-top: 0.15vmin solid #94a3b8;
}

.s-water-line {
  position: absolute;
  background: #cbd5e1;
  height: 0.1vmin;
  border-radius: 0.1vmin;
}

.sw1 {
  top: 1vmin;
  left: 3vmin;
  width: 5vmin;
}
.sw2 {
  top: 1.8vmin;
  left: 10vmin;
  width: 7vmin;
}
.sw3 {
  top: 2.5vmin;
  left: 5vmin;
  width: 3vmin;
}
.sw4 {
  top: 1.2vmin;
  left: 18vmin;
  width: 4vmin;
}

.painting-mask {
  position: absolute;
  top: 1.4vmin;
  left: 1.4vmin;
  height: calc(100% - 2.8vmin);
  width: 0%;
  overflow: hidden;
  z-index: 2;
  transition: width 1.4s cubic-bezier(0.34, 1.2, 0.64, 1);
}

.theme-switch input:checked ~ .easel-frame .painting-mask {
  width: calc(100% - 2.8vmin);
}

.painting-scene {
  position: absolute;
  top: 0;
  left: 0;
  width: 24vmin;
  height: 14.6vmin;
  background: linear-gradient(to bottom, #fda4af, #fde047 60%, #7dd3fc 100%);
}

.p-sun {
  position: absolute;
  bottom: 5.5vmin;
  left: 11vmin;
  width: 4vmin;
  height: 4vmin;
  background: #ffffff;
  border-radius: 50%;
  box-shadow:
    0 0 2vmin #fef08a,
    0 0 4vmin rgba(253, 224, 71, 0.8);
  transition:
    transform 1.2s cubic-bezier(0.34, 1.56, 0.64, 1) 1.2s,
    box-shadow 1.2s ease 1.2s;
}

.theme-switch input:checked ~ .easel-frame .painting-mask .p-sun {
  transform: translateY(-1.5vmin) scale(1.2);
  box-shadow:
    0 0 3vmin #ffffff,
    0 0 6vmin #fde047,
    0 0 10vmin rgba(253, 224, 71, 0.6);
}

.p-mountain {
  position: absolute;
  border-radius: 40% 60% 50% 50% / 50% 50% 60% 40%;
  box-shadow:
    inset 0.4vmin 0.4vmin 1vmin rgba(255, 255, 255, 0.3),
    inset -0.4vmin -0.4vmin 1vmin rgba(0, 0, 0, 0.2);
}

.pm1 {
  bottom: -2vmin;
  left: 0.5vmin;
  width: 8vmin;
  height: 6vmin;
  background: linear-gradient(135deg, #d946ef, #9333ea);
  transform: rotate(-10deg);
  z-index: 2;
}
.pm2 {
  bottom: -3vmin;
  left: 5vmin;
  width: 11vmin;
  height: 8vmin;
  background: linear-gradient(135deg, #f43f5e, #be123c);
  transform: rotate(5deg);
  z-index: 1;
}
.pm3 {
  bottom: -1.5vmin;
  left: 13vmin;
  width: 8vmin;
  height: 5.5vmin;
  background: linear-gradient(135deg, #c084fc, #7e22ce);
  transform: rotate(-5deg);
  z-index: 2;
}

.p-water {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 3.5vmin;
  background: linear-gradient(to bottom, #ec4899, #0284c7);
  z-index: 3;
  overflow: hidden;
  box-shadow: inset 0 0.5vmin 0.5vmin rgba(0, 0, 0, 0.1);
}

.p-reflection {
  position: absolute;
  top: 0;
  left: 11vmin;
  width: 4.5vmin;
  height: 100%;
  background: linear-gradient(
    to bottom,
    rgba(253, 224, 71, 0.9),
    rgba(253, 224, 71, 0)
  );
  filter: blur(0.5vmin);
  opacity: 0;
  transform: translateX(0);
  transition: opacity 1.2s ease 1.2s;
}

.theme-switch input:checked ~ .easel-frame .painting-mask .p-reflection {
  opacity: 1;
  animation: water-sway 3s infinite alternate ease-in-out 1.2s;
}

@keyframes water-sway {
  0% {
    transform: translateX(-0.3vmin) skewX(-5deg);
  }
  100% {
    transform: translateX(0.3vmin) skewX(5deg);
  }
}

.p-water-shimmer {
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(
    90deg,
    transparent 0,
    transparent 2.5vmin,
    rgba(255, 255, 255, 0.4) 2.8vmin,
    transparent 3.1vmin
  );
  opacity: 0;
  transform: translateX(-5vmin);
}

.theme-switch input:checked ~ .easel-frame .painting-mask .p-water-shimmer {
  opacity: 1;
  animation: water-flow 5s linear infinite;
}

@keyframes water-flow {
  100% {
    transform: translateX(0);
  }
}

.p-bird {
  position: absolute;
  width: 2vmin;
  height: 1.5vmin;
  opacity: 0;
  z-index: 5;
}

.pb1 {
  top: 2vmin;
  left: -3vmin;
}
.pb2 {
  top: 3.5vmin;
  left: -5vmin;
  transform: scale(0.65);
}

.theme-switch input:checked ~ .easel-frame .painting-mask .pb1 {
  animation: bird-fly 8s cubic-bezier(0.4, 0, 0.6, 1) infinite 1.8s;
}

.theme-switch input:checked ~ .easel-frame .painting-mask .pb2 {
  animation: bird-fly 9s cubic-bezier(0.4, 0, 0.6, 1) infinite 2.5s;
}

@keyframes bird-fly {
  0% {
    transform: translateX(0) translateY(0) scale(1);
    opacity: 0;
  }
  10% {
    opacity: 0.85;
  }
  30% {
    transform: translateX(10vmin) translateY(-1vmin) scale(0.9);
  }
  60% {
    transform: translateX(20vmin) translateY(1vmin) scale(0.8);
  }
  90% {
    opacity: 0.85;
  }
  100% {
    transform: translateX(32vmin) translateY(-2vmin) scale(0.7);
    opacity: 0;
  }
}

.wing {
  position: absolute;
  top: 0;
  width: 1vmin;
  height: 1vmin;
  border-top: 0.2vmin solid #0f172a;
  border-radius: 50%;
}

.wing-l {
  left: 0;
  transform-origin: right center;
  animation: flap-l 0.3s infinite alternate ease-in-out;
}

.wing-r {
  right: 0;
  transform-origin: left center;
  animation: flap-r 0.3s infinite alternate-reverse ease-in-out;
}

@keyframes flap-l {
  0% {
    transform: rotate(-35deg);
  }
  100% {
    transform: rotate(25deg);
  }
}

@keyframes flap-r {
  0% {
    transform: rotate(35deg);
  }
  100% {
    transform: rotate(-25deg);
  }
}

.brush-tracker {
  position: absolute;
  top: -1vmin;
  left: -1vmin;
  width: 4vmin;
  height: 18vmin;
  z-index: 10;
  transition: transform 1.4s cubic-bezier(0.34, 1.2, 0.64, 1);
}

.theme-switch input:checked ~ .easel-frame .brush-tracker {
  transform: translateX(25vmin);
}

.paintbrush {
  width: 100%;
  height: 100%;
  transform-origin: center 65%;
  transition: transform 0.4s ease;
  filter: drop-shadow(1vmin 1vmin 1vmin rgba(0, 0, 0, 0.3));
}

.theme-switch input:checked ~ .easel-frame .brush-tracker .paintbrush {
  animation: paint-stroke 1.4s ease-in-out;
  transform: rotate(15deg);
}

@keyframes paint-stroke {
  0% {
    transform: rotate(0deg) translateY(0);
  }
  20% {
    transform: rotate(-20deg) translateY(-1.5vmin);
  }
  40% {
    transform: rotate(15deg) translateY(1.5vmin);
  }
  60% {
    transform: rotate(-15deg) translateY(-1vmin);
  }
  80% {
    transform: rotate(18deg) translateY(1vmin);
  }
  100% {
    transform: rotate(15deg) translateY(0);
  }
}

.handle {
  position: absolute;
  top: 0;
  left: 1.2vmin;
  width: 1.6vmin;
  height: 10vmin;
  background: linear-gradient(to right, #451a03, #b45309, #451a03);
  border-radius: 1vmin 1vmin 0 0;
  box-shadow:
    inset -0.2vmin 0 0.5vmin rgba(0, 0, 0, 0.6),
    inset 0.1vmin 0 0.3vmin rgba(255, 255, 255, 0.2);
}

.handle::after {
  content: "";
  position: absolute;
  top: 1vmin;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(to bottom, transparent, rgba(0, 0, 0, 0.3));
}

.ferrule {
  position: absolute;
  top: 10vmin;
  left: 1.2vmin;
  width: 1.6vmin;
  height: 2.2vmin;
  background: linear-gradient(to right, #64748b, #f8fafc, #64748b);
  border-radius: 0.2vmin;
  box-shadow: inset 0 0.2vmin 0.5vmin rgba(0, 0, 0, 0.4);
}

.ferrule::after {
  content: "";
  position: absolute;
  top: 0.6vmin;
  left: 0;
  width: 100%;
  height: 0.2vmin;
  background: rgba(0, 0, 0, 0.3);
}

.ferrule::before {
  content: "";
  position: absolute;
  top: 1.4vmin;
  left: 0;
  width: 100%;
  height: 0.2vmin;
  background: rgba(0, 0, 0, 0.3);
}

.bristles {
  position: absolute;
  top: 12.2vmin;
  left: 1.2vmin;
  width: 1.6vmin;
  height: 4vmin;
  background: linear-gradient(to right, #1c1917, #78716c, #1c1917);
  border-radius: 0 0 50% 50%;
  overflow: hidden;
  box-shadow: 0 0.5vmin 1vmin rgba(0, 0, 0, 0.3);
}

.bristles::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 60%;
  background: linear-gradient(to bottom, transparent, #fb7185, #f43f5e);
  filter: blur(0.1vmin);
}

.magic-spark {
  position: absolute;
  bottom: 0.5vmin;
  left: 2vmin;
  width: 0.8vmin;
  height: 0.8vmin;
  background: #fde047;
  border-radius: 50%;
  box-shadow:
    0 0 1.5vmin #fde047,
    0 0 3vmin #ffffff;
  opacity: 0;
  pointer-events: none;
}

.theme-switch input:checked ~ .easel-frame .brush-tracker .s1 {
  animation: spark-drop 0.9s infinite ease-out 0.2s;
}
.theme-switch input:checked ~ .easel-frame .brush-tracker .s2 {
  animation: spark-drop 0.7s infinite ease-out 0.5s;
  left: 1.2vmin;
}
.theme-switch input:checked ~ .easel-frame .brush-tracker .s3 {
  animation: spark-drop 1s infinite ease-out 0.8s;
  left: 2.5vmin;
}

@keyframes spark-drop {
  0% {
    transform: translateY(0) scale(1);
    opacity: 1;
  }
  50% {
    opacity: 0.8;
  }
  100% {
    transform: translateY(5vmin) scale(0);
    opacity: 0;
  }
}

.theme-switch:active .easel-frame {
  transform: scale(0.97);
}
